// Polymarket CLOB V2 signing parity with the OFFICIAL client (@polymarket/clob-client-v2, pinned in gen_vectors.mjs).
// test/fixtures/polymarket/vectors.json is generated by gen_vectors.mjs from that package. Harbour's own order builder, order
// digest, order body, ClobAuth signature and L2 HMAC must reproduce the official bytes. A live cross-check against the package
// itself runs when it is installed (dev only, skipped otherwise).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { build } from 'esbuild';
import { sign, serializeSignature } from 'viem/accounts';
import { readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const src = fileURLToPath(new URL('../src/', import.meta.url));
const V = JSON.parse(readFileSync(new URL('./fixtures/polymarket/vectors.json', import.meta.url), 'utf8'));
const out = await build({ stdin: { contents: `export * from './core/predictions/polymarket';`, resolveDir: src, sourcefile: 'e.ts', loader: 'ts' }, bundle: true, write: false, platform: 'node', format: 'esm', logLevel: 'silent' });
const file = path.join(tmpdir(), `harbour-pm-golden-${process.pid}.mjs`); writeFileSync(file, out.outputFiles[0].text);
const pm = await import(pathToFileURL(file).href);
const signHex = async (hash) => serializeSignature(await sign({ hash, privateKey: V.key }));
const harbourOrder = (c) => pm.buildOrder({ maker: V.address, tokenId: V.tokenId, side: c.side, price: c.price, size: c.size, tickSize: Number(c.tick), builder: c.builder, now: V.now, salt: Number(c.official.salt) });

for (const c of V.orders) {
  test(`order matches the official client: ${c.name}`, async () => {
    const o = harbourOrder(c); const w = c.official;
    assert.deepEqual({ makerAmount: o.makerAmount, takerAmount: o.takerAmount, timestamp: o.timestamp, metadata: o.metadata, builder: o.builder, side: o.side === 0 ? 'BUY' : 'SELL' },
      { makerAmount: w.makerAmount, takerAmount: w.takerAmount, timestamp: w.timestamp, metadata: w.metadata, builder: w.builder, side: w.side });
    const signature = await signHex(pm.orderDigest(o, c.negRisk));
    assert.equal(signature, w.signature, 'EIP-712 order signature');
    const body = JSON.parse(pm.orderBody(o, signature, 'api-key-1', 'GTC'));
    assert.deepEqual(body.order, JSON.parse(JSON.stringify(w.body.order)), 'order JSON');
    assert.equal(body.owner, w.body.owner); assert.equal(body.orderType, w.body.orderType); assert.equal(body.deferExec, w.body.deferExec);
  });
}
test(`order amount rounding matches the official getOrderRawAmounts (${V.amounts.length} cases)`, () => {
  for (const [tick, side, price, size, maker, taker] of V.amounts) {
    const a = pm.orderAmounts(side, price, size, Number(tick));
    assert.deepEqual([a.makerAmount, a.takerAmount], [maker, taker], `${tick} ${side} price=${price} size=${size}`);
  }
});
test('dust sizes are refused instead of producing zero-amount orders (the official client would emit 0)', () => {
  assert.throws(() => pm.orderAmounts('BUY', 0.01, 0.001, 0.01), /too small/i);
});
for (const c of V.clobAuth) test(`ClobAuth signature matches the official client (nonce ${c.nonce})`, async () => {
  assert.equal(await signHex(pm.clobAuthDigest(V.address, c.timestamp, c.nonce)), c.signature);
});
for (const c of V.hmac) test(`L2 HMAC matches the official client: ${c.method} ${c.path}`, async () => {
  assert.equal(await pm.l2Signature(c.secret, c.timestamp, c.method, c.path, c.body), c.signature);
});

test('cross-check against @polymarket/clob-client-v2 (dev dependency, optional)', async (t) => {
  let sdk; let viem; let chains;
  try { sdk = await import('@polymarket/clob-client-v2'); viem = await import('viem'); chains = await import('viem/chains'); } catch { return t.skip('@polymarket/clob-client-v2 is not installed'); }
  const wallet = viem.createWalletClient({ account: (await import('viem/accounts')).privateKeyToAccount(V.key), chain: chains.polygon, transport: viem.http('http://127.0.0.1:1') });
  const realRandom = Math.random; const realNow = Date.now;
  try {
    for (const c of V.orders) {
      Math.random = () => c.rand; Date.now = () => V.now;
      const signed = await new sdk.OrderBuilder(wallet, 137, sdk.SignatureTypeV2.EOA).buildOrder({ tokenID: V.tokenId, price: c.price, size: c.size, side: c.side, ...(c.builder ? { builderCode: c.builder } : {}) }, { tickSize: c.tick, negRisk: c.negRisk });
      const o = harbourOrder(c);
      assert.equal(await signHex(pm.orderDigest(o, c.negRisk)), signed.signature, c.name);
      assert.equal(o.makerAmount, signed.makerAmount); assert.equal(o.takerAmount, signed.takerAmount);
    }
  } finally { Math.random = realRandom; Date.now = realNow; }
});
